internal static class SszRuntimeHelpers
{
    internal static string GenerateSource(string helperNamespace) =>
"""
// <auto-generated/>
#nullable enable
using Nethermind.Int256;
using Nethermind.Serialization.Ssz.Merkleization;
using System;
using System.Buffers.Binary;
using System.Collections;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;

namespace __SSZ_HELPER_NAMESPACE__;

internal static class SszCodecHelpers
{
    private const int SszOffsetSize = 4;

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal static void EncodeSszOffset(Span<byte> data, int offset) =>
        BinaryPrimitives.WriteInt32LittleEndian(data, offset);

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal static int DecodeSszOffset(ReadOnlySpan<byte> data) =>
        BinaryPrimitives.ReadInt32LittleEndian(data);

    internal static T ThrowInvalidSszData<T>(string typeName, string message) =>
        throw new InvalidDataException($"Invalid SSZ data for {typeName}: {message}");

    internal static void ThrowInvalidSszData(string typeName, string message) =>
        throw new InvalidDataException($"Invalid SSZ data for {typeName}: {message}");

    internal static void ThrowInvalidSszValue(string typeName, string fieldName, string message) =>
        throw new InvalidDataException($"Invalid SSZ value for {typeName}.{fieldName}: {message}");

    internal static void ValidateSszExactLength(int actualLength, int expectedLength, string typeName)
    {
        if (actualLength != expectedLength)
        {
            ThrowInvalidSszData(typeName, $"expected {expectedLength} bytes but found {actualLength}.");
        }
    }

    internal static void ValidateSszMinimumLength(int actualLength, int minimumLength, string typeName)
    {
        if (actualLength < minimumLength)
        {
            ThrowInvalidSszData(typeName, $"expected at least {minimumLength} bytes but found {actualLength}.");
        }
    }

    internal static void ValidateSszMultipleOf(int actualLength, int itemLength, string typeName)
    {
        if (actualLength % itemLength != 0)
        {
            ThrowInvalidSszData(typeName, $"expected a multiple of {itemLength} bytes but found {actualLength}.");
        }
    }

    internal static void ValidateSszDynamicOffsets(ReadOnlySpan<byte> data, int fixedLength, string typeName, ReadOnlySpan<int> offsets)
    {
        ValidateSszMinimumLength(data.Length, fixedLength, typeName);

        if (offsets.Length is 0)
        {
            return;
        }

        if (offsets[0] != fixedLength)
        {
            ThrowInvalidSszData(typeName, $"expected the first offset to be {fixedLength} but found {offsets[0]}.");
        }

        int previous = fixedLength;
        for (int index = 0; index < offsets.Length; index++)
        {
            int current = offsets[index];
            if (current < previous)
            {
                ThrowInvalidSszData(typeName, $"offset #{index} is out of order ({current} < {previous}).");
            }

            if (current > data.Length)
            {
                ThrowInvalidSszData(typeName, $"offset #{index} ({current}) exceeds the input length {data.Length}.");
            }

            previous = current;
        }
    }

    internal static int ValidateSszVariableItemCount(ReadOnlySpan<byte> data, int firstOffset, string typeName)
    {
        ValidateSszMinimumLength(data.Length, SszOffsetSize, typeName);

        if (firstOffset < SszOffsetSize)
        {
            ThrowInvalidSszData(typeName, $"expected the first offset to be at least {SszOffsetSize} but found {firstOffset}.");
        }

        if (firstOffset > data.Length)
        {
            ThrowInvalidSszData(typeName, $"the first offset {firstOffset} exceeds the input length {data.Length}.");
        }

        if (firstOffset % SszOffsetSize != 0)
        {
            ThrowInvalidSszData(typeName, $"the first offset {firstOffset} is not aligned to {SszOffsetSize}-byte offsets.");
        }

        return firstOffset / SszOffsetSize;
    }

    internal static void ValidateSszNextOffset(ReadOnlySpan<byte> data, int currentOffset, int nextOffset, string typeName)
    {
        if (nextOffset < currentOffset)
        {
            ThrowInvalidSszData(typeName, $"offsets are out of order ({nextOffset} < {currentOffset}).");
        }

        if (nextOffset > data.Length)
        {
            ThrowInvalidSszData(typeName, $"offset {nextOffset} exceeds the input length {data.Length}.");
        }
    }

    internal static void ValidateSszVectorLength<T>(ReadOnlySpan<T> items, int expectedLength, string typeName, string fieldName)
    {
        if (items.Length != expectedLength)
        {
            ThrowInvalidSszValue(typeName, fieldName, $"expected {expectedLength} elements but found {items.Length}.");
        }
    }

    internal static void ValidateSszListLimit<T>(ReadOnlySpan<T> items, ulong limit, string typeName, string fieldName)
    {
        if ((ulong)items.Length > limit)
        {
            ThrowInvalidSszValue(typeName, fieldName, $"expected at most {limit} elements but found {items.Length}.");
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal static byte[] DecodeSszByteList(ReadOnlySpan<byte> data, ulong limit, string typeName, string fieldName)
    {
        ValidateSszListLimit(data, limit, typeName, fieldName);
        byte[] result = global::System.GC.AllocateUninitializedArray<byte>(data.Length);
        data.CopyTo(result);
        return result;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    internal static byte[] DecodeSszByteVector(ReadOnlySpan<byte> data, int expectedLength, string typeName, string fieldName)
    {
        if (data.Length != expectedLength)
        {
            ThrowInvalidSszValue(typeName, fieldName, $"expected {expectedLength} elements but found {data.Length}.");
        }

        byte[] result = global::System.GC.AllocateUninitializedArray<byte>(expectedLength);
        data.CopyTo(result);
        return result;
    }

    internal static void ValidateSszBitvectorLength(BitArray? bits, int expectedLength, string typeName, string fieldName)
    {
        int actualLength = bits?.Length ?? 0;
        if (bits is null || actualLength != expectedLength)
        {
            ThrowInvalidSszValue(typeName, fieldName, $"expected {expectedLength} bits but found {actualLength}.");
        }
    }

    internal static void ValidateSszBitlistLimit(BitArray? bits, ulong limit, string typeName, string fieldName)
    {
        if (bits is not null && (ulong)bits.Length > limit)
        {
            ThrowInvalidSszValue(typeName, fieldName, $"expected at most {limit} bits but found {bits.Length}.");
        }
    }

    internal static void DecodeSszBitVector(ReadOnlySpan<byte> data, int vectorLength, out BitArray value)
    {
        ValidateSszExactLength(data.Length, (int)(((uint)vectorLength + 7) / 8), $"bitvector[{vectorLength}]");
        value = Nethermind.Serialization.Ssz.Ssz.DecodeBitvector(data, vectorLength);
    }

    internal static void DecodeSszBitList(ReadOnlySpan<byte> data, ulong limit, string typeName, out BitArray value)
    {
        ValidateSszMinimumLength(data.Length, 1, typeName);
        if (data[^1] != 0)
        {
            ulong bitLength = (ulong)(data.Length - 1) * 8 + (uint)System.Numerics.BitOperations.Log2(data[^1]);
            if (bitLength > limit) ThrowInvalidSszData(typeName, $"bit length {bitLength} exceeds the SSZ limit {limit}.");
        }
        value = Nethermind.Serialization.Ssz.Ssz.DecodeBitlist(data);
    }

    internal static void MerkleizeBasicVector<T>(ReadOnlySpan<T> values, int itemSize, ulong length, out UInt256 root)
        where T : struct
    {
        ulong chunkCount = GetSszChunkCount(length, itemSize);
        Merkle.Merkleize(out root, MemoryMarshal.AsBytes(values), chunkCount);
    }

    internal static void MerkleizeBasicList<T>(ReadOnlySpan<T> values, int itemSize, ulong limit, out UInt256 root)
        where T : struct
    {
        ulong chunkCount = GetSszChunkCount(limit, itemSize);
        Merkle.Merkleize(out root, MemoryMarshal.AsBytes(values), chunkCount);
        Merkle.MixIn(ref root, values.Length);
    }

    internal static void MerkleizeProgressiveBasicList<T>(ReadOnlySpan<T> values, out UInt256 root)
        where T : struct
    {
        Merkle.MerkleizeProgressive(out root, MemoryMarshal.AsBytes(values));
        Merkle.MixIn(ref root, values.Length);
    }

    internal delegate void EncodeItems<T>(Span<byte> span, ReadOnlySpan<T> items);

    private static ulong GetSszChunkCount(ulong count, int itemSize) =>
        checked(count / 32 * (ulong)itemSize + (count % 32 * (ulong)itemSize + 31) / 32);

    private static void MerkleizeBasicCollectionWithConverter<T>(
        ReadOnlySpan<T> values, int itemSize, ulong chunkCount, EncodeItems<T> encode, out UInt256 root)
    {
        // Basic SSZ widths divide a chunk. Encode bounded batches directly into the tree.
        if (itemSize <= 32 && (itemSize & (itemSize - 1)) == 0)
        {
            Span<byte> batch = stackalloc byte[256];
            Merkleizer merkleizer = new(stackalloc UInt256[Merkle.NextPowerOfTwoExponent(chunkCount) + 1]);
            int itemsPerBatch = batch.Length / itemSize;
            while (!values.IsEmpty)
            {
                int count = Math.Min(values.Length, itemsPerBatch);
                int encodedLength = count * itemSize;
                encode(batch[..encodedLength], values[..count]);
                int paddedLength = (encodedLength + 31) / 32 * 32;
                batch[encodedLength..paddedLength].Clear();
                foreach (UInt256 chunk in MemoryMarshal.Cast<byte, UInt256>(batch[..paddedLength]))
                {
                    merkleizer.Feed(chunk);
                }
                values = values[count..];
            }
            merkleizer.CalculateRoot(out root);
            return;
        }

        const int StackByteLimit = 256;
        int byteLength = checked(values.Length * itemSize);
        scoped Span<byte> bytes;
        byte[]? rented = null;
        if (byteLength <= StackByteLimit)
        {
            Span<byte> stack = stackalloc byte[StackByteLimit];
            bytes = stack[..byteLength];
        }
        else
        {
            rented = System.Buffers.ArrayPool<byte>.Shared.Rent(byteLength);
            bytes = rented.AsSpan(0, byteLength);
        }
        try
        {
            Debug.Assert(bytes.Length == byteLength, "SSZ collection buffer length must match item count and item size.");
            encode(bytes, values);
            Merkle.Merkleize(out root, bytes, chunkCount);
        }
        finally
        {
            if (rented is not null) System.Buffers.ArrayPool<byte>.Shared.Return(rented);
        }
    }

    internal static void MerkleizeBasicVectorWithConverter<T>(
        ReadOnlySpan<T> values, int itemSize, ulong length, EncodeItems<T> encode, out UInt256 root)
    {
        ulong chunkCount = GetSszChunkCount(length, itemSize);
        MerkleizeBasicCollectionWithConverter(values, itemSize, chunkCount, encode, out root);
    }

    internal static void MerkleizeBasicListWithConverter<T>(
        ReadOnlySpan<T> values, int itemSize, ulong limit, EncodeItems<T> encode, out UInt256 root)
    {
        ulong chunkCount = GetSszChunkCount(limit, itemSize);
        MerkleizeBasicCollectionWithConverter(values, itemSize, chunkCount, encode, out root);
        Merkle.MixIn(ref root, values.Length);
    }

    internal static void MerkleizeProgressiveBasicListWithConverter<T>(
        ReadOnlySpan<T> values, int itemSize, EncodeItems<T> encode, out UInt256 root)
    {
        if (itemSize <= 32 && (itemSize & (itemSize - 1)) == 0)
        {
            Span<UInt256> subtrees = stackalloc UInt256[17];
            int subtreeCount = 0;
            int offset = 0;
            ulong capacity = 1;
            while (offset < values.Length)
            {
                int count = (int)Math.Min((ulong)(values.Length - offset), capacity * (ulong)(32 / itemSize));
                MerkleizeBasicCollectionWithConverter(values.Slice(offset, count), itemSize, capacity, encode, out subtrees[subtreeCount++]);
                offset += count;
                capacity *= 4;
            }
            MerkleizeProgressiveSubtrees(subtrees[..subtreeCount], out root);
            Merkle.MixIn(ref root, values.Length);
            return;
        }

        const int StackByteLimit = 256;
        int byteLength = checked(values.Length * itemSize);
        scoped Span<byte> bytes;
        byte[]? rented = null;
        if (byteLength <= StackByteLimit)
        {
            Span<byte> stack = stackalloc byte[StackByteLimit];
            bytes = stack[..byteLength];
        }
        else
        {
            rented = System.Buffers.ArrayPool<byte>.Shared.Rent(byteLength);
            bytes = rented.AsSpan(0, byteLength);
        }
        try
        {
            Debug.Assert(bytes.Length == byteLength, "SSZ collection buffer length must match item count and item size.");
            encode(bytes, values);
            Merkle.MerkleizeProgressive(out root, bytes);
        }
        finally
        {
            if (rented is not null) System.Buffers.ArrayPool<byte>.Shared.Return(rented);
        }
        Merkle.MixIn(ref root, values.Length);
    }

    internal static void MerkleizeProgressiveBitList(BitArray? value, out UInt256 root)
    {
        if (value is null)
        {
            root = UInt256.Zero;
            Merkle.MixIn(ref root, 0);
            return;
        }
        Merkle.MerkleizeProgressive(out root, value);
    }

    internal delegate void FeedItem<T>(ref Merkleizer merkleizer, T item);

    private static void MerkleizeCompositeCollectionWithConverter<T>(
        ReadOnlySpan<T> items, ulong limit, FeedItem<T> feed, out UInt256 root)
    {
        Merkleizer merkleizer = new(stackalloc UInt256[Merkle.NextPowerOfTwoExponent(limit) + 1]);
        foreach (T item in items)
        {
            feed(ref merkleizer, item);
        }
        merkleizer.CalculateRoot(out root);
    }

    internal static void MerkleizeCompositeVectorWithConverter<T>(ReadOnlySpan<T> items, ulong length, FeedItem<T> feed, out UInt256 root)
    {
        Debug.Assert((ulong)items.Length == length, "Vector items count must equal declared length");
        MerkleizeCompositeCollectionWithConverter(items, length, feed, out root);
    }

    internal static void MerkleizeCompositeListWithConverter<T>(ReadOnlySpan<T> items, ulong limit, FeedItem<T> feed, out UInt256 root)
    {
        MerkleizeCompositeCollectionWithConverter(items, limit, feed, out root);
        Merkle.MixIn(ref root, items.Length);
    }

    internal static void MerkleizeCompositeProgressiveListWithConverter<T>(ReadOnlySpan<T> items, FeedItem<T> feed, out UInt256 root)
    {
        // Progressive subtrees contain 1, 4, 16, ... leaves; only their roots need retaining.
        Span<UInt256> subtrees = stackalloc UInt256[17];
        Span<UInt256> scratch = stackalloc UInt256[33];
        int subtreeCount = 0;
        int offset = 0;
        ulong capacity = 1;
        while (offset < items.Length)
        {
            int count = (int)Math.Min((ulong)(items.Length - offset), capacity);
            Merkleizer merkleizer = new(scratch[..(Merkle.NextPowerOfTwoExponent(capacity) + 1)]);
            foreach (T item in items.Slice(offset, count)) feed(ref merkleizer, item);
            merkleizer.CalculateRoot(out subtrees[subtreeCount++]);
            offset += count;
            capacity *= 4;
        }
        MerkleizeProgressiveSubtrees(subtrees[..subtreeCount], out root);
        Merkle.MixIn(ref root, items.Length);
    }

    internal static void MerkleizeProgressiveSubtrees(ReadOnlySpan<UInt256> subtrees, out UInt256 root)
    {
        Span<UInt256> scratch = stackalloc UInt256[2];
        root = UInt256.Zero;
        for (int i = subtrees.Length - 1; i >= 0; i--)
        {
            Merkleizer branch = new(scratch[..2]);
            branch.Feed(subtrees[i]);
            branch.Feed(root);
            branch.CalculateRoot(out root);
        }
    }

    internal static void MerkleizeWithConverter<T>(T value, FeedItem<T> feed, out UInt256 root)
    {
        Span<UInt256> chunk = stackalloc UInt256[1];
        Merkleizer merkleizer = new(chunk);
        feed(ref merkleizer, value);
        merkleizer.CalculateRoot(out root);
    }
}
""".Replace("__SSZ_HELPER_NAMESPACE__", helperNamespace);
}
